// The vanilla overworld, generated by Horizon's port of the game's world generator.
//
// Vanilla builds a chunk in stages. Terrain, biomes, carvers and structure starts
// (the proto chunk) depend only on the chunk itself. Features (trees, ores, lakes...)
// are placed per chunk but may write into the 8 chunks around it, so a chunk is only
// finished once it and all 8 neighbours have been decorated, which in turn needs proto
// chunks two rings out. Decorating a chunk borrows its 3×3 protos, so two decorations
// that overlap never run at the same time.

use super::{Chunk, ChunkSource, WorldInfo};
use anyhow::{Context, Result, anyhow};
use crossbeam_channel::{Receiver, Sender};
use horizon_core::position::ChunkPos;
use horizon_world::{
    registry::BlockRegistry,
    worldgen::generator::{GeneratorData, GeneratorWorker, OverworldGenerator, ProtoChunk},
};
use std::{
    collections::HashMap,
    path::Path,
    sync::{Arc, Mutex},
    thread,
};
use tokio::sync::oneshot;
use tracing::{debug, info, warn};

type Pos = (i32, i32);
type Waiter = oneshot::Sender<Result<Arc<Chunk>, String>>;

enum Job {
    Proto(Pos),
    Decorate(Pos, Vec<Box<ProtoChunk>>),
    Finish(Pos, Box<ProtoChunk>),
}

#[derive(Default)]
struct Slot {
    /// `None` while the proto is being generated or is lent out.
    proto: Option<Box<ProtoChunk>>,
    generating: bool,
    decorating: bool,
    decorated: bool,
    finishing: bool,
    finished: bool,
    failed: Option<String>,
}

#[derive(Default)]
struct State {
    slots: HashMap<Pos, Slot>,
    finished: HashMap<Pos, Arc<Chunk>>,
    waiting: HashMap<Pos, Vec<Waiter>>,
}

struct Shared {
    state: Mutex<State>,
    jobs: Sender<Job>,
    min_y: i32,
    height: u32,
}

pub struct VanillaWorld {
    info: WorldInfo,
    shared: Arc<Shared>,
    spawn_column: [i32; 2],
}

impl VanillaWorld {
    pub fn open(data_dir: &Path, seed: i64, threads: usize) -> Result<Self> {
        crate::prepare::check(data_dir)?;
        let facts = std::fs::read(data_dir.join("facts.json")).context("reading facts.json")?;
        let registry: &'static BlockRegistry =
            Box::leak(Box::new(BlockRegistry::from_facts_json(&facts[..]).context("reading facts.json")?));
        let data = GeneratorData::load(&data_dir.join("worldgen"), registry)
            .map_err(|e| anyhow!("loading the world generator's data: {e}"))?;
        for warning in data.warnings() {
            debug!("worldgen data: {warning}");
        }
        let generator =
            OverworldGenerator::for_world(data.clone(), seed, "minecraft:normal", "minecraft:overworld", true)
                .map_err(|e| anyhow!("setting up the world generator: {e}"))?;
        for (feature, kind) in generator.unsupported_features() {
            warn!("feature {feature} ({kind}) isn't supported by the generator and will be skipped");
        }

        let (min_y, height) = generator.level();
        let spawn_column = generator.spawn_position().map_err(|e| anyhow!("finding the spawn point: {e}"))?;
        let info = WorldInfo {
            min_y,
            height: height as u32,
            sea_level: generator.sea_level(),
            is_flat: false,
            biome_names: data.biome_names().iter().map(|n| n.to_string()).collect(),
        };

        let (jobs, queue) = crossbeam_channel::unbounded();
        let shared = Arc::new(Shared { state: Mutex::new(State::default()), jobs, min_y, height: height as u32 });
        for i in 0..threads.max(1) {
            let worker = generator.worker();
            let queue: Receiver<Job> = queue.clone();
            let shared = shared.clone();
            thread::Builder::new()
                .name(format!("worldgen-{i}"))
                .spawn(move || run_worker(worker, queue, shared))
                .context("spawning a worldgen thread")?;
        }
        info!("vanilla world generator ready (seed {seed}, {threads} threads)");
        Ok(Self { info, shared, spawn_column })
    }
}

#[async_trait::async_trait]
impl ChunkSource for VanillaWorld {
    async fn get(&self, x: i32, z: i32) -> Result<Arc<Chunk>> {
        let rx = {
            let mut state = self.shared.state.lock().unwrap();
            if let Some(chunk) = state.finished.get(&(x, z)) {
                return Ok(chunk.clone());
            }
            let (tx, rx) = oneshot::channel();
            state.waiting.entry((x, z)).or_default().push(tx);
            schedule(&mut state, &self.shared.jobs);
            rx
        };
        rx.await.map_err(|_| anyhow!("world generator dropped chunk {x} {z}"))?.map_err(|e| anyhow!(e))
    }

    fn info(&self) -> &WorldInfo {
        &self.info
    }

    async fn spawn_point(&self) -> Result<[f64; 3]> {
        let [x, z] = self.spawn_column;
        let chunk = self.get(x >> 4, z >> 4).await?;
        let y = chunk.surface((x & 15) as usize, (z & 15) as usize);
        Ok([x as f64 + 0.5, y as f64, z as f64 + 0.5])
    }
}

fn around(c: Pos, r: i32) -> impl Iterator<Item = Pos> {
    (-r..=r).flat_map(move |dz| (-r..=r).map(move |dx| (c.0 + dx, c.1 + dz)))
}

/// Starts whatever work the waiting chunks can use next.
fn schedule(state: &mut State, jobs: &Sender<Job>) {
    let wanted: Vec<Pos> = state.waiting.keys().copied().collect();
    for c in wanted {
        if let Some(error) = around(c, 2).find_map(|p| state.slots.get(&p).and_then(|s| s.failed.clone())) {
            fail(state, c, &error);
            continue;
        }
        // Each proto is generated once; afterwards it is either here, lent to a
        // decoration, or turned into a finished chunk.
        for p in around(c, 2) {
            if !state.slots.contains_key(&p) {
                state.slots.insert(p, Slot { generating: true, ..Slot::default() });
                let _ = jobs.send(Job::Proto(p));
            }
        }
        for d in around(c, 1) {
            let ready = {
                let slot = &state.slots[&d];
                !slot.decorated && !slot.decorating
            } && around(d, 1).all(|p| state.slots.get(&p).is_some_and(|s| s.proto.is_some()));
            if ready {
                // Row-major 3×3, the order Horizon's decorate expects.
                let region: Vec<Box<ProtoChunk>> =
                    around(d, 1).map(|p| state.slots.get_mut(&p).unwrap().proto.take().unwrap()).collect();
                state.slots.get_mut(&d).unwrap().decorating = true;
                let _ = jobs.send(Job::Decorate(d, region));
            }
        }
        let all_decorated = around(c, 1).all(|p| state.slots.get(&p).is_some_and(|s| s.decorated));
        let slot = state.slots.get_mut(&c).unwrap();
        if all_decorated && !slot.finishing && !slot.finished {
            if let Some(proto) = slot.proto.take() {
                slot.finishing = true;
                let _ = jobs.send(Job::Finish(c, proto));
            }
        }
    }
}

fn fail(state: &mut State, c: Pos, error: &str) {
    for waiter in state.waiting.remove(&c).unwrap_or_default() {
        let _ = waiter.send(Err(error.to_owned()));
    }
}

fn run_worker(mut worker: GeneratorWorker, queue: Receiver<Job>, shared: Arc<Shared>) {
    while let Ok(job) = queue.recv() {
        match job {
            Job::Proto(pos) => {
                let result = catch(|| worker.generate_proto(ChunkPos::new(pos.0, pos.1)).map_err(|e| e.to_string()));
                let mut state = shared.state.lock().unwrap();
                let slot = state.slots.entry(pos).or_default();
                slot.generating = false;
                match result {
                    Ok(proto) => slot.proto = Some(Box::new(proto)),
                    Err(e) => {
                        warn!("generating chunk {} {}: {e}", pos.0, pos.1);
                        slot.failed = Some(e);
                    }
                }
                schedule(&mut state, &shared.jobs);
            }
            Job::Decorate(pos, region) => {
                let mut array: [ProtoChunk; 9] = match region.into_iter().map(|b| *b).collect::<Vec<_>>().try_into() {
                    Ok(a) => a,
                    Err(_) => unreachable!("a decoration region is 3×3"),
                };
                let result = catch(|| worker.decorate(&mut array).map(|_| ()).map_err(|e| e.to_string()));
                if let Err(e) = &result {
                    // Vanilla logs and carries on with what was placed, and so do we.
                    warn!("decorating chunk {} {}: {e}", pos.0, pos.1);
                }
                let mut state = shared.state.lock().unwrap();
                for (p, proto) in around(pos, 1).zip(array) {
                    state.slots.get_mut(&p).unwrap().proto = Some(Box::new(proto));
                }
                let slot = state.slots.get_mut(&pos).unwrap();
                slot.decorating = false;
                slot.decorated = true;
                schedule(&mut state, &shared.jobs);
            }
            Job::Finish(pos, proto) => {
                let chunk = Arc::new(to_chunk(&proto, pos, shared.min_y, shared.height));
                drop(proto);
                let mut state = shared.state.lock().unwrap();
                let slot = state.slots.get_mut(&pos).unwrap();
                slot.finishing = false;
                slot.finished = true;
                state.finished.insert(pos, chunk.clone());
                for waiter in state.waiting.remove(&pos).unwrap_or_default() {
                    let _ = waiter.send(Ok(chunk.clone()));
                }
                schedule(&mut state, &shared.jobs);
            }
        }
    }
}

fn catch<T>(f: impl FnOnce() -> Result<T, String>) -> Result<T, String> {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or_else(|_| Err("generator panicked".into()))
}

fn to_chunk(proto: &ProtoChunk, (cx, cz): Pos, min_y: i32, height: u32) -> Chunk {
    let mut chunk = Chunk::empty(cx, cz, min_y, height, 0);
    let (bx, bz) = (cx * 16, cz * 16);
    for (i, section) in chunk.sections.iter_mut().enumerate() {
        let base = min_y + i as i32 * 16;
        for y in 0..16 {
            for z in 0..16 {
                for x in 0..16 {
                    let state = proto.block(bx + x as i32, base + y as i32, bz + z as i32).0;
                    section.blocks[(y * 16 + z) * 16 + x] = state as u16;
                }
            }
        }
        for qy in 0..4 {
            for qz in 0..4 {
                for qx in 0..4 {
                    let biome = proto.biome_id_at(bx + qx * 4, base + qy * 4, bz + qz * 4).0;
                    section.biomes[((qy * 4 + qz) * 4 + qx) as usize] = biome as u16;
                }
            }
        }
    }
    chunk
}

/// The world seed from server.properties' `level-seed`, read the way vanilla reads it.
pub fn parse_seed(text: &str) -> Option<i64> {
    let text = text.trim();
    if text.is_empty() {
        return None;
    }
    Some(text.parse::<i64>().unwrap_or_else(|_| java_string_hash(text) as i64))
}

fn java_string_hash(s: &str) -> i32 {
    s.encode_utf16().fold(0i32, |h, c| h.wrapping_mul(31).wrapping_add(c as i32))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn seeds_read_like_vanilla() {
        assert_eq!(parse_seed(""), None);
        assert_eq!(parse_seed(" 12345 "), Some(12345));
        assert_eq!(parse_seed("-4172144997902289642"), Some(-4172144997902289642));
        // "hello".hashCode() in Java
        assert_eq!(parse_seed("hello"), Some(99162322));
        assert_eq!(parse_seed("glacier"), Some(java_string_hash("glacier") as i64));
    }

    #[test]
    fn regions_are_row_major() {
        let r: Vec<Pos> = around((10, 20), 1).collect();
        assert_eq!(r[0], (9, 19));
        assert_eq!(r[1], (10, 19));
        assert_eq!(r[4], (10, 20));
        assert_eq!(r[8], (11, 21));
    }
}
